int get_interface_settings(struct fst_card_info *card, struct fst_port_info *port, struct ifreq *ifr) {
    int ret = 0;
    struct sync_config sync;
    int size = 0;

    (void)card; // unused parameter

    switch (port->hw_if) {
        case IF_TYPE_T1:
            ifr->ifr_type = IFT_T1;
            size = sizeof(struct sync_t1_config);
            break;
        case IF_TYPE_E1:
            ifr->ifr_type = IFT_E1;
            size = sizeof(struct sync_e1_config);
            break;
        case IF_TYPE_SONET:
            ifr->ifr_type = IFT_SONET;
            size = sizeof(struct sync_sonet_config);
            break;
        default:
            return -EFAULT;
    }

    if (ifr->ifr_size < size) {
        return -ENOMEM;
    }

    sync.clock_rate = port->clock_rate;
    sync.clock_type = port->clock_type;

    if (copy_to_user(ifr->ifr_data, &sync, size) != 0) {
        return -EFAULT;
    }

    ifr->ifr_size = size;
    return ret;
}

int get_interface_settings(struct fst_card_info *card, struct fst_port_info *port, struct ifreq *ifr) {
    int ret = 0;
    struct sync_data {
        int clock_rate;
        int type;
    } sync_info;

    /* Determine line type based on the hardware interface */
    switch (port->hw_if) {
        case IF_TYPE_E1:
            sync_info.type = SYNC_TYPE_E1;
            break;
        case IF_TYPE_T1:
            sync_info.type = SYNC_TYPE_T1;
            break;
        case IF_TYPE_J1:
            sync_info.type = SYNC_TYPE_J1;
            break;
        default:
            sync_info.type = 0;
            break;
    }

    /* Set clock rate */
    sync_info.clock_rate = port->clock_rate;

    /* Check if the requested size is sufficient */
    if (ifr->ifr_data_size < sizeof(sync_info)) {
        return -ENOMEM;
    }

    /* Copy data to user space */
    if (copy_to_user(ifr->ifr_data, &sync_info, sizeof(sync_info))) {
        return -EFAULT;
    }

    /* Update size in interface request */
    ifr->ifr_data_size = sizeof(sync_info);

    return ret;
}
